60	static struct qemu_plugin_scoreboard *vcpu_state;
61	static char *outfile_path;
62	
63	// PC-trigger mode: when enter_pc_arg is non-zero (set via plugin arg
64	// `enter_pc=0x...`), the CSR-insn matcher is bypassed entirely and the
65	// drain callback is registered only for instructions whose vaddr equals
66	// enter_pc_arg. The kind reported on the drain is HYBRID_HANDOFF_ENTER
67	// (entry into vsim), matching marker-mode enter-marker semantics.
68	static uint64_t enter_pc_arg;
69	static int pc_mode;
70	
71	// Oracle exit-drain mode (verify_oracle F1): when exit_marker_mode or
72	// exit_pc_mode is set (plugin args `exit_marker=1` / `exit_pc=0x...`), a
73	// pure-QEMU run produces the differential verifier's reference state. Every
74	// insn gets an exec callback: the tick ARMS on the
75	// ROI exit boundary (EXIT marker match, or vaddr == exit_pc) and DRAINS on
76	// the next callback. Exec callbacks fire before their insn executes, so the
77	// armed drain captures "after the boundary insn retired" -- exactly vsim's
78	// exit-drain record (DPC = next insn to execute) -- and reports that next
79	// insn's vaddr as pc, correct even when the boundary insn branches.
80	// Exclusive with the other trigger modes: the oracle run never hands off.
81	//
82	// drain_pc=0x... (optional modifier): drain at the first post-arm tick whose
83	// vaddr equals drain_pc, instead of the very next tick. The differential
84	// harness passes vsim's actual drained pc here: vsim's DMI halt lands a
85	// variable 0-3 insns past the trigger (the core keeps retiring while the
86	// haltreq propagates), and the two states only compare equal when both
87	// sides sample the SAME architectural point. If vsim's pc is never reached
88	// (a real control-flow divergence), the oracle never drains and QEMU runs
89	// to completion -- the caller sees exit != 200.
90	static uint64_t exit_pc_arg;
91	static int      exit_pc_mode;
92	static int      exit_marker_mode;
93	static uint64_t drain_pc_arg;
94	static int      drain_pc_set;
95	static volatile int oracle_armed;
96	
97	// Drain-at-exit mode (F14): when drain_at_exit_mode is set (plugin arg
98	// `drain_at_exit=1`), the plugin registers a per-insn exec callback that
99	// bumps `atexit_insn_count`, and a `qemu_plugin_register_atexit_cb` that
100	// drains state on natural program exit (e.g. semihosting EXIT). The
101	// atexit callback overrides s.minstret with the plugin counter so the
102	// caller gets a true retired-insn count
103	// independent of QEMU's PMU semantics (which can return host ticks on
104	// system-mode without `-icount`). `drained_already` suppresses the
105	// atexit path if another trigger (marker/PC) drained first.
106	static int      drain_at_exit_mode;
107	static volatile int drained_already;
108	static uint64_t atexit_insn_count;
