110	static struct qemu_plugin_register *find_reg(GArray *regs, const char *name)
111	{
112	    for (guint i = 0; i < regs->len; i++) {
113	        qemu_plugin_reg_descriptor *rd =
114	            &g_array_index(regs, qemu_plugin_reg_descriptor, i);
115	        if (g_ascii_strcasecmp(rd->name, name) == 0) {
116	            return rd->handle;
117	        }
118	    }
119	    return NULL;
120	}
121	
122	// Lazily resolves register handles. The plugin's vcpu_init runs before
123	// QEMU has registered the dynamic gdb coprocessors (FPU, virtual, csr,
124	// vector), so qemu_plugin_get_registers() returns only the 33 core CPU
125	// regs at that moment. By the time the entry trigger fires, all dynamic
126	// features are registered and a fresh call returns the full list.
127	static void resolve_handles(VcpuRegs *v)
128	{
129	    g_autoptr(GArray) regs = qemu_plugin_get_registers();
130	    for (int i = 0; i < 32; i++) {
131	        v->gpr[i] = find_reg(regs, hybrid_gpr_names[i]);
132	        v->fpr[i] = find_reg(regs, hybrid_fpr_names[i]);
133	    }
134	    v->pc = find_reg(regs, "pc");
135	
136	    v->mstatus  = find_reg(regs, "mstatus");
137	    v->mepc     = find_reg(regs, "mepc");
138	    v->mtvec    = find_reg(regs, "mtvec");
139	    v->mcause   = find_reg(regs, "mcause");
140	    v->mtval    = find_reg(regs, "mtval");
141	    v->mscratch = find_reg(regs, "mscratch");
142	    v->medeleg  = find_reg(regs, "medeleg");
143	    v->mideleg  = find_reg(regs, "mideleg");
144	    v->mip      = find_reg(regs, "mip");
145	    v->mie      = find_reg(regs, "mie");
146	    v->mcycle   = find_reg(regs, "mcycle");
147	    v->minstret = find_reg(regs, "minstret");
148	    v->satp     = find_reg(regs, "satp");
149	
150	    char buf[16];
151	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++) {
152	        g_snprintf(buf, sizeof(buf), "pmpcfg%d", i);
153	        v->pmpcfg[i] = find_reg(regs, buf);
154	    }
155	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++) {
156	        g_snprintf(buf, sizeof(buf), "pmpaddr%d", i);
157	        v->pmpaddr[i] = find_reg(regs, buf);
158	    }
159	
160	    v->vstart = find_reg(regs, "vstart");
161	    v->vxsat  = find_reg(regs, "vxsat");
162	    v->vxrm   = find_reg(regs, "vxrm");
163	    v->vcsr   = find_reg(regs, "vcsr");
164	    v->vtype  = find_reg(regs, "vtype");
165	    v->vl     = find_reg(regs, "vl");
166	    v->vlenb  = find_reg(regs, "vlenb");
167	    for (int i = 0; i < 32; i++) {
168	        g_snprintf(buf, sizeof(buf), "v%d", i);
169	        v->vreg[i] = find_reg(regs, buf);
170	    }
171	}
