173	static uint64_t read_reg64(struct qemu_plugin_register *h)
174	{
175	    if (!h) return 0;
176	    g_autoptr(GByteArray) buf = g_byte_array_new();
177	    int sz = qemu_plugin_read_register(h, buf);
178	    if (sz <= 0) return 0;
179	    uint64_t v = 0;
180	    memcpy(&v, buf->data, sz < 8 ? (size_t) sz : 8);
181	    return v;
182	}
183	
184	// Reads up to `dst_max` bytes from a register handle. Returns the byte
185	// count written (0 on failure or NULL handle). Used for vector regs whose
186	// width = vlenb bytes.
187	static size_t read_reg_bytes(struct qemu_plugin_register *h,
188	                             uint8_t *dst, size_t dst_max)
189	{
190	    if (!h || dst_max == 0) return 0;
191	    g_autoptr(GByteArray) buf = g_byte_array_new();
192	    int sz = qemu_plugin_read_register(h, buf);
193	    if (sz <= 0) return 0;
194	    size_t n = (size_t) sz < dst_max ? (size_t) sz : dst_max;
195	    memcpy(dst, buf->data, n);
196	    return n;
197	}
198	
199	// Atomic on POSIX: write to .tmp, fsync, rename.
200	static int write_state_atomic(const struct hybrid_state_v1 *s, const char *path)
201	{
202	    char tmp[PATH_MAX];
203	    g_snprintf(tmp, sizeof(tmp), "%s.tmp.%d", path, (int) getpid());
204	    int fd = open(tmp, O_WRONLY | O_CREAT | O_TRUNC, 0600);
205	    if (fd < 0) {
206	        perror("hybrid_handoff: open tmp");
207	        return -1;
208	    }
209	    ssize_t want = (ssize_t) sizeof(*s);
210	    ssize_t got = write(fd, s, sizeof(*s));
211	    if (got != want) {
212	        perror("hybrid_handoff: write");
213	        close(fd);
214	        unlink(tmp);
215	        return -1;
216	    }
217	    fsync(fd);
218	    close(fd);
219	    if (rename(tmp, path) != 0) {
220	        perror("hybrid_handoff: rename");
221	        unlink(tmp);
222	        return -1;
223	    }
224	    return 0;
225	}
226	
227	// Drain CPU state to outfile_path. pc is computed by the caller (from a
228	// HandoffSite for trigger paths, or 0 for the atexit path which lacks an
229	// insn context). If minstret_override is non-zero, it replaces QEMU's PMU
230	// minstret in the state file (used by drain_at_exit mode to record a
231	// plugin-counted retired-insn total). Does NOT call exit -- caller
232	// decides exit(200) (normal trigger) vs _exit(200) (inside atexit chain).
233	static void drain_state_to_file(unsigned int vcpu_idx, uint64_t pc,
234	                                uint64_t minstret_override)
235	{
236	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
237	    resolve_handles(v);
238	    struct hybrid_state_v1 s = {0};
239	    s.magic   = HYBRID_STATE_MAGIC;
240	    s.version = HYBRID_STATE_VERSION;
241	    s.flags   = HYBRID_FLAG_RV64;
242	    s.hart_id = vcpu_idx;
243	    s.priv    = 3;
244	    s.pc      = pc;
245	    for (int i = 0; i < 32; i++) s.gpr[i] = read_reg64(v->gpr[i]);
246	
247	    // Floating-point: only set FP flag if at least one handle was bound,
248	    // i.e. QEMU advertised the FPU feature (D extension).
249	    int has_fp = 0;
250	    for (int i = 0; i < 32; i++) {
251	        s.fpr[i] = read_reg64(v->fpr[i]);
252	        if (v->fpr[i]) has_fp = 1;
253	    }
254	    if (has_fp) s.flags |= HYBRID_FLAG_FP;
255	
256	    s.mstatus  = read_reg64(v->mstatus);
257	    s.mepc     = read_reg64(v->mepc);
258	    s.mtvec    = read_reg64(v->mtvec);
259	    s.mcause   = read_reg64(v->mcause);
260	    s.mtval    = read_reg64(v->mtval);
261	    s.mscratch = read_reg64(v->mscratch);
262	    s.medeleg  = read_reg64(v->medeleg);
263	    s.mideleg  = read_reg64(v->mideleg);
264	    s.mip      = read_reg64(v->mip);
265	    s.mie      = read_reg64(v->mie);
266	    s.mcycle   = read_reg64(v->mcycle);
267	    s.minstret = minstret_override ? minstret_override
268	                                   : read_reg64(v->minstret);
269	    s.satp     = read_reg64(v->satp);
270	
271	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++)
272	        s.pmpcfg[i] = read_reg64(v->pmpcfg[i]);
273	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++)
274	        s.pmpaddr[i] = read_reg64(v->pmpaddr[i]);
275	
276	    // Vector: only set V flag if QEMU advertised the V extension. vlenb
277	    // bounds the per-register byte count copied into vreg[]. The policy
278	    // helper (hybrid_v_drain_policy) decides SKIP/OK/ABORT from the
279	    // handle truthiness so we don't conflate "stub missing vlenb" with
280	    // "V disabled at runtime"; see include/hybrid/v_drain_policy.h.
281	    s.vstart = read_reg64(v->vstart);
282	    s.vxsat  = read_reg64(v->vxsat);
283	    s.vxrm   = read_reg64(v->vxrm);
284	    s.vcsr   = read_reg64(v->vcsr);
285	    s.vtype  = read_reg64(v->vtype);
286	    s.vl     = read_reg64(v->vl);
287	    s.vlenb  = read_reg64(v->vlenb);
288	    int has_other_v = (v->vstart || v->vxsat || v->vxrm || v->vcsr
289	                       || v->vtype || v->vl);
290	    if (!has_other_v) {
291	        for (int i = 0; i < 32; i++)
292	            if (v->vreg[i]) { has_other_v = 1; break; }
293	    }
294	    HybridVDrainPolicy vpol = hybrid_v_drain_policy(
295	        v->vlenb != NULL, has_other_v, s.vlenb);
296	    if (vpol == HYBRID_V_DRAIN_ABORT) {
297	        if (v->vlenb == NULL)
298	            fprintf(stderr,
299	                    "hybrid_handoff: stub advertised V CSRs/regs but not "
300	                    "vlenb; refusing to drain partial V state\n");
301	        else
302	            fprintf(stderr,
303	                    "hybrid_handoff: vlenb=%" PRIu64 " exceeds the wire-format "
304	                    "ceiling HYBRID_VLEN_BYTES_MAX=%d (VLEN %d); refusing to "
305	                    "truncate V registers\n",
306	                    s.vlenb, HYBRID_VLEN_BYTES_MAX,
307	                    8 * HYBRID_VLEN_BYTES_MAX);
308	        exit(2);
309	    }
310	    if (vpol == HYBRID_V_DRAIN_OK) {
311	        s.flags |= HYBRID_FLAG_V;
312	        /* The policy guarantees vlenb <= HYBRID_VLEN_BYTES_MAX here, so the
313	         * full live register fits the wire-format slot -- no clamp (L11). */
314	        for (int i = 0; i < 32; i++)
315	            (void) read_reg_bytes(v->vreg[i],
316	                                  &s.vreg[(size_t) i * HYBRID_VLEN_BYTES_MAX],
317	                                  (size_t) s.vlenb);
318	    }
319	
320	    if (write_state_atomic(&s, outfile_path) != 0) {
321	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
322	        exit(2);
323	    }
324	    fprintf(stderr,
325	            "hybrid_handoff: drained state to %s (pc=%#" PRIx64 "), exiting\n",
326	            outfile_path, s.pc);
