329	static void on_handoff(unsigned int vcpu_idx, void *udata)
330	{
331	    const HandoffSite *site = (const HandoffSite *) udata;
332	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
333	    // F14: suppress the atexit drain path now that we have a real trigger.
334	    drained_already = 1;
335	    // PC via translation-time vaddr+size; reading the gdbstub PC inside the
336	    // exec callback can lag the actual current insn when V instructions
337	    // retire just before the trigger (TCG defers PC writes for performance).
338	    drain_state_to_file(vcpu_idx, compute_handoff_pc(site), 0);
339	    // 200 == kExitHandoffToQemu in verilator/src/hybrid/exit_codes.hpp.
340	    // Distinguishes drain from workload completion (0) so the orchestrator
341	    // can decide the next spawn.
342	    exit(200);
343	}
344	
345	// F14: per-insn tick. Increments a global counter every retired insn so the
346	// drain-at-exit path can report a true retired-insn total (independent of
347	// QEMU's PMU semantics).
348	static void on_count_tick(unsigned int vcpu_idx, void *udata)
349	{
350	    (void) vcpu_idx;
351	    (void) udata;
352	    atexit_insn_count++;
353	}
354	
355	// F14: atexit drain. Fires when QEMU exits naturally (e.g. guest semihosting
356	// EXIT). The semihosting EXIT runs on the vCPU thread, so current_cpu is
357	// still set and qemu_plugin_read_register works. If any other trigger
358	// already drained, return immediately (drained_already guards against
359	// double drain). Inside an atexit handler, exit() is UB per C11 7.22.4.4;
360	// use _exit() to skip the rest of the atexit chain.
361	static void on_atexit(qemu_plugin_id_t id, void *udata)
362	{
363	    (void) id;
364	    (void) udata;
365	    if (drained_already) return;
366	    if (!drain_at_exit_mode) return;
367	    // pc=0 is a positive marker that the atexit path drained (no trigger).
368	    drain_state_to_file(0, 0, atexit_insn_count);
369	    fflush(stderr);
370	    _exit(200);
371	}
372	
373	// Per-insn tick for oracle exit-drain mode. udata is this insn's HandoffSite.
374	// When armed (the exit boundary's own tick ran), this tick fires before its
375	// insn executes, so a drain here records the post-retire state of the
376	// boundary insn with pc = the dynamically-next insn's vaddr. drain_pc (when
377	// set) delays the drain to the first post-arm tick at that pc, so both legs
378	// sample the same architectural point despite vsim's variable halt slack.
379	static void on_oracle_tick(unsigned int vcpu_idx, void *udata)
380	{
381	    const HandoffSite *site = (const HandoffSite *) udata;
382	    if (oracle_armed
383	        && (!drain_pc_set || site->vaddr == drain_pc_arg)) {
384	        drain_state_to_file(vcpu_idx, site->vaddr, 0);
385	        // 200 == kExitHandoffToQemu; distinguishes drain from workload exit.
386	        exit(200);
387	    }
388	    if (exit_pc_mode ? (site->vaddr == exit_pc_arg)
389	                     : (site->kind == HYBRID_HANDOFF_EXIT)) {
390	        oracle_armed = 1;
391	    }
392	}
