394	static void vcpu_tb_trans(qemu_plugin_id_t id, struct qemu_plugin_tb *tb)
395	{
396	    (void) id;
397	    size_t n = qemu_plugin_tb_n_insns(tb);
398	
399	    for (size_t i = 0; i < n; i++) {
400	        struct qemu_plugin_insn *insn = qemu_plugin_tb_get_insn(tb, i);
401	
402	        // F14 count tick: registered FIRST so the count is incremented
403	        // before any trigger callback can call exit(200). NO_REGS keeps
404	        // the per-insn cost minimal (a single uint64 add).
405	        if (drain_at_exit_mode) {
406	            qemu_plugin_register_vcpu_insn_exec_cb(
407	                insn, on_count_tick, QEMU_PLUGIN_CB_NO_REGS, NULL);
408	        }
409	
410	        // Oracle exit-drain mode: exclusive with every other mode (enforced
411	        // at install), so it owns the insn's registration outright. The site
412	        // carries the marker kind so the tick can arm on the EXIT marker.
413	        if (exit_marker_mode || exit_pc_mode) {
414	            HandoffSite *site = g_new0(HandoffSite, 1);
415	            site->kind  = HYBRID_HANDOFF_NONE;
416	            site->vaddr = qemu_plugin_insn_vaddr(insn);
417	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
418	            if (exit_marker_mode && site->size == 4) {
419	                uint32_t raw = 0;
420	                if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) == sizeof(raw))
421	                    hybrid_match_handoff_insn(raw, &site->kind);
422	            }
423	            qemu_plugin_register_vcpu_insn_exec_cb(
424	                insn, on_oracle_tick, QEMU_PLUGIN_CB_R_REGS, site);
425	            continue;
426	        }
427	
428	        if (pc_mode) {
429	            // PC-trigger mode: vaddr-only match. qemu_plugin_insn_size lets
430	            // a future fixture park enter_pc on a compressed insn -- next-PC
431	            // is computed from the API-reported size, not assumed to be 4.
432	            if (qemu_plugin_insn_vaddr(insn) != enter_pc_arg) continue;
433	            HandoffSite *site = g_new0(HandoffSite, 1);
434	            site->kind  = HYBRID_HANDOFF_ENTER;
435	            site->vaddr = qemu_plugin_insn_vaddr(insn);
436	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
437	            qemu_plugin_register_vcpu_insn_exec_cb(
438	                insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
439	            continue;
440	        }
441	
442	        // Marker-trigger mode (default).
443	        // The markers are `slti x0, x0, 0x5A0/0x5A1`, always 32-bit
444	        // (sz==4): SLTI has no compressed form, so the sz!=4 skip is
445	        // exact, not an approximation.
446	        size_t sz = qemu_plugin_insn_size(insn);
447	        if (sz != 4) continue;
448	        uint32_t raw = 0;
449	        if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) != sizeof(raw))
450	            continue;
451	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
452	        if (!hybrid_match_handoff_insn(raw, &kind)) continue;
453	        HandoffSite *site = g_new0(HandoffSite, 1);
454	        site->kind  = kind;
455	        site->vaddr = qemu_plugin_insn_vaddr(insn);
456	        site->size  = (uint32_t) sz;
457	        qemu_plugin_register_vcpu_insn_exec_cb(
458	            insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
459	    }
460	}
