29	  for (int i = 0; i < 32; ++i)
30	    cmp(r, "x" + std::to_string(i), ref.gpr[i], got.gpr[i]);
31	
32	  if (ref.flags & HYBRID_FLAG_FP)
33	    for (int i = 0; i < 32; ++i)
34	      cmp(r, "f" + std::to_string(i), ref.fpr[i], got.fpr[i]);
35	
36	  if (ref.flags & HYBRID_FLAG_V) {
37	    cmp(r, "vstart", ref.vstart, got.vstart);
38	    cmp(r, "vtype", ref.vtype, got.vtype);
39	    cmp(r, "vl", ref.vl, got.vl);
40	    cmp(r, "vlenb", ref.vlenb, got.vlenb);
41	    cmp(r, "vxsat", ref.vxsat, got.vxsat);
42	    cmp(r, "vxrm", ref.vxrm, got.vxrm);
43	    cmp(r, "vcsr", ref.vcsr, got.vcsr);
44	
45	    // One compared "field" per vector register; report the first differing
46	    // byte as "v<i>[<byte>]".
47	    for (int i = 0; i < 32; ++i) {
48	      ++r.compared;
49	      const uint8_t* a = &ref.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
50	      const uint8_t* b = &got.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
51	      for (int j = 0; j < HYBRID_VLEN_BYTES_MAX; ++j) {
52	        if (a[j] != b[j]) {
53	          r.diffs.push_back({"v" + std::to_string(i) + "[" +
54	                                 std::to_string(j) + "]",
55	                             a[j], b[j]});
56	          break;
57	        }
58	      }
59	    }
60	  }
61	
62	  return r;
